class Solution {
  public long minOperations(int[] nums) {
    List<Long> even = new ArrayList<>(), odd = new ArrayList<>();
    for (int len = 1; len <= 10; len++) {
      int half = (len + 1) / 2;
      long start = (long) Math.pow(10, half - 1), end = (long) Math.pow(10, half);
      for (long h = start; h < end; h++) {
        String s = Long.toString(h);
        StringBuilder sb = new StringBuilder(s);
        String tail =
            new StringBuilder(len % 2 == 0 ? s : s.substring(0, s.length() - 1))
                .reverse()
                .toString();
        long p = Long.parseLong(sb.append(tail).toString());
        if (p % 2 == 0) even.add(p);
        else odd.add(p);
      }
    }
    long[] ev = even.stream().mapToLong(x -> x).toArray(),
        od = odd.stream().mapToLong(x -> x).toArray();
    java.util.Arrays.sort(ev);
    java.util.Arrays.sort(od);
    long total = 0;
    for (int x : nums) {
      long[] list = x % 2 == 0 ? ev : od;
      int idx = java.util.Arrays.binarySearch(list, x);
      long best;
      if (idx >= 0) best = 0;
      else {
        int ins = -idx - 1;
        best = Long.MAX_VALUE;
        if (ins < list.length) best = Math.min(best, list[ins] - x);
        if (ins > 0) best = Math.min(best, x - list[ins - 1]);
      }
      total += best / 2;
    }
    return total;
  }
}
